contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address[] memory tos, uint[] memory vs) public {
        require(tos.length > 0);
        require(vs.length >= tos.length);
        require(msg.sender == address(this));
        for (uint i = 0; i < tos.length; i++) {
            require(vs[i] <= type(uint256).max / 1000000000000000000);
        }

        bool reverted;
        bool returnedTrue;
        try c.transfer(tos, vs) returns (bool ok) {
            reverted = false;
            returnedTrue = ok;
        } catch {
            reverted = true;
            returnedTrue = false;
        }

        assert(!reverted && returnedTrue);
    }

    receive() external payable {}
}

